/**
 * The Virtual Participant's port of the Model inference geography resolver,
 * held to the Python resolver's answers: the cases file the Configuration page
 * is tested against, regenerated by lma-ai-stack/test/test_inference_geography.py.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

import { GEOGRAPHY, GLOBAL, IN_REGION, resolveForGeography, resolveModelId } from './inference-geography.js';

interface Case {
    region: string;
    geography: string;
    model: string;
    expected: string | null;
    verified: boolean;
}

const CASES: Case[] = JSON.parse(
    readFileSync(
        new URL(
            './../../../lma-ai-stack/source/ui/src/components/configuration/inference-geography-cases.json',
            import.meta.url,
        ).pathname.replace('/dist/', '/src/'),
        'utf8',
    ),
);

const HAIKU = 'global.anthropic.claude-haiku-4-5-20251001-v1:0';

test('the port agrees with the Python resolver on every shared case', () => {
    assert.ok(CASES.length > 100);
    for (const c of CASES) {
        const result = resolveForGeography(c.model, c.geography, c.region);
        assert.equal(result.modelId, c.expected, `${c.region} ${c.geography} ${c.model}`);
        assert.equal(result.verified, c.verified, `${c.region} ${c.geography} ${c.model}`);
    }
});

test('the DOM resolver model runs within the geography it is configured for', async () => {
    assert.equal(await resolveModelId(HAIKU, 'eu-west-1', async () => GEOGRAPHY), 'eu.anthropic.claude-haiku-4-5-20251001-v1:0');
    assert.equal(await resolveModelId(HAIKU, 'eu-west-1', async () => GLOBAL), HAIKU);
});

test('a geography with no id for the model is refused rather than called outside it', async () => {
    await assert.rejects(resolveModelId(HAIKU, 'us-east-1', async () => IN_REGION), /Model inference geography/);
});
